class Solution {
public:
    int minimumSwaps(vector<int>& nums) {
        int n = nums.size();
        int i = 0, j = n - 1;
        for (int k = 0; k < n; k++) if (nums[k] < nums[i]) i = k;
        for (int k = n - 1; k >= 0; k--) if (nums[k] > nums[j]) j = k;
        int ans = i + (n - 1 - j);
        return i > j ? ans - 1 : ans;
    }
};

